// Real Add: mutates the list
public void SaveClockEntry(ClockEntry clockEntry) => _clockEntries.Add(clockEntry);

// Real Where: reads the list, returns a query, does not mutate
public IEnumerable<ClockEntry> GetEmployeeClockEntries(int employeeId, DateTime startDate, DateTime endDate) =>
    _clockEntries.Where(entry => entry.EmployeeId == employeeId && entry.ClockOut != null
        && entry.ClockIn >= startDate && entry.ClockIn <= endDate);
